const pointsPerType = (typeCount: number): number =>
  typeCount > TYPE_BONUS_THRESHOLD ? POINTS_PER_TYPE_WITH_BONUS : POINTS_PER_TYPE;

export const scoreArmy = (army: Card[]): number => {
  if (!containsSphinx(army)) return 0;
  const typeCount = countDistinctTypes(army);
  return typeCount * pointsPerType(typeCount);
};
